def evaluate_expression(expr_text, variables):
    try:
        # Replace variable names with their values
        for name, value in variables.items():
            expr_text = expr_text.replace(name, str(value))
        # Evaluate the expression safely
        return eval(expr_text, {'__builtins__': None}, {})
    except Exception:
        raise ValueError(f"Invalid expression: {expr_text}")

