def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    variables = {}
    expressions = []

    for elem in root:
        if elem.tag == 'variable':
            name = elem.attrib['name']
            variables[name] = int(elem.attrib['value'])
        elif elem.tag == 'expression':
            name = elem.attrib['name']
            text = elem.text.strip()
            expressions.append((name, text))

    return variables, expressions

def evaluate_expression(name, text, variables):
    def evaluate(s):
        stack = []
        i = 0
        while i < len(s):
            if s[i] == ' ':
                i += 1
                continue
            if s[i] == '(':
                stack.append(i)
                i += 1
            elif s[i] == ')':
                start = stack.pop()
                sub_expr = s[start+1:i]
                val = evaluate(sub_expr)
                i += 1
                return val
            elif s[i] in '+-*/':
                i += 1
            elif s[i].isdigit():
                num = 0
                while i < len(s) and s[i].isdigit():
                    num = num * 10 + int(s[i])
                    i += 1
                stack.append(num)
            elif s[i] in variables:
                stack.append(variables[s[i]])
                i += 1
            else:
                i += 1
        return sum(stack) if '+' in s else stack[0] if stack else 0

    try:
        return evaluate(text)
    except:
        return 0

