import sys
import xml.etree.ElementTree as ET

def parse_xml(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except (ET.ParseError, FileNotFoundError) as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(2)

    variables = []
    outputs = []

    for elem in root:
        if elem.tag == 'variable':
            variables.append(elem)
        elif elem.tag == 'output':
            outputs.append(elem)

    return variables, outputs

def evaluate_expression(expr, bindings):
    try:
        # Safely evaluate the expression with the given bindings
        local_vars = bindings.copy()
        return eval(expr, {'__builtins__': None}, local_vars)
    except:
        return 0  # Fallback, though problem states expressions are valid

def main():
    if len(sys.argv) != 2:
        print("usage: report_tool.py XML_FILE", file=sys.stderr)
        sys.exit(2)

    xml_path = sys.argv[1]
    variables, outputs = parse_xml(xml_path)

    bindings = {}

    for var_elem in variables:
        var_name = var_elem.get('name')
        expr = var_elem.get('expression')
        if not var_name or not expr:
            print(f"Error: Invalid variable element: {var_elem.tag} with missing attributes", file=sys.stderr)
            sys.exit(2)
        bindings[var_name] = evaluate_expression(expr, bindings)

    for out_elem in outputs:
        out_name = out_elem.get('name')
        expr = out_elem.get('expression')
        if not out_name or not expr:
            print(f"Error: Invalid output element: {out_elem.tag} with missing attributes", file=sys.stderr)
            sys.exit(2)
        value = evaluate_expression(expr, bindings)
        print(f"{out_name}={value}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET

def main():
    if len(sys.argv) != 2:
        print('usage: report_tool.py XML_FILE', file=sys.stderr)
        sys.exit(2)

    xml_file = sys.argv[1]
    try:
        tree = ET.parse(xml_file)
        root = tree.getroot()
    except ET.ParseError:
        print('Error parsing XML file.', file=sys.stderr)
        sys.exit(1)
    except FileNotFoundError:
        print('File not found.', file=sys.stderr)
        sys.exit(1)

    variables = {}
    outputs = []

    for elem in root:
        if elem.tag == 'variable':
            name = elem.get('name')
            expression = elem.get('expression')
            # Evaluate the expression and store the result in variables
            variables[name] = eval(expression, {}, variables)
        elif elem.tag == 'output':
            name = elem.get('name')
            expression = elem.get('expression')
            # Store the output for later printing
            outputs.append((name, eval(expression, {}, variables)))

    for name, value in outputs:
        print(f'{name}={value}')

if __name__ == '__main__':
    main()
